/**
 * Config documents, on `src/api/schema.d.ts` — generated by `make types` from
 * the real pydantic models and held to the tree by `make lint-generated`.
 *
 * `group` is a key into `ConfigList.groups`, not a display string, so the
 * index page gets its headings, their order and their one-line blurbs from the
 * server -- adding a document to `config_service.EDITABLE` puts it on screen
 * with no frontend change. `readonly` marks the assembled system prompts, which
 * render in the same pane with no Save and no draft tracking.
 */

import type { components } from '@/api/schema'

type Schemas = components['schemas']

export type ConfigDocMeta = Schemas['ConfigSummary']

/** A heading on the index, with the sentence saying what lives under it. */
export type ConfigGroup = Schemas['ConfigGroup']

/** A shape the press keeps asserting that the current ontology refuses. */
export type OntologyRejectedShape = Schemas['OntologyRejectedShape']

/**
 * What `localStorage` holds per document. Hand-written and staying that way:
 * it never crosses the wire.
 *
 * `base` is the document's `version` at the moment the draft was taken, and it
 * is the whole reason this is an object rather than a bare string. Without it
 * every unsaved buffer looks identical, so a draft left over from a file that
 * has since changed on disk is indistinguishable from
 * something you typed a minute ago -- and the only button on offer writes it
 * over the file.
 */
export interface StoredDraft {
  content: string
  /** `ConfigDoc.version` when the draft was taken; `''` for pre-versioned drafts. */
  base: string
}

/**
 * What the editor pane holds, which is EITHER shape the two document routes
 * return.
 *
 * The backend splits them deliberately: `ConfigDocOut` for an editable
 * document, `AssembledDocOut` for a generated system prompt, rather than one
 * model with both field sets optional. Its own docstring gives the reason — a
 * shared model emits `generated_from: null, tokens_estimate: null` on every
 * editable document, two keys that were never there, on the response the
 * settings editor loads every time it opens a file.
 *
 * `ConfigEditor.vue` renders both, so what it holds is the editable shape plus
 * the two fields only the assembled route sends. Expressed as exactly that, so
 * the optionality on screen matches the optionality on the wire.
 */
export type ConfigDoc = Schemas['ConfigDocOut'] &
  Partial<Pick<Schemas['AssembledDocOut'], 'generated_from' | 'tokens_estimate'>>

/**
 * `PUT /api/config/{key}`. Adds `history` and `restart_required`, the latter
 * saying in the reader's words what the save did not reach in the running
 * process: a rebuild a live run blocked, one that failed, a schedule that could
 * not be re-pointed. Empty for every other document, and for a save that landed
 * whole.
 */
export type SaveResponse = Schemas['ConfigSaved']

export type AnchorApplyResult = Schemas['AnchorsApplied']

/** `GET /config`. `items` is optional on the model. */
export type ConfigList = Schemas['ConfigList']

export type ServerDraft = Schemas['DraftOut']

/** A row in `.history/`: what `GET /config/{key}/history` lists. */
export type ConfigSnapshot = Schemas['ConfigSnapshot']

/** The same row with its text, from `GET /config/{key}/history/{name}`. */
export type ConfigSnapshotFull = Schemas['ConfigSnapshotOut']

export type ConfigHistory = Schemas['ConfigHistory']

/**
 * The 409 from `PUT /config/{key}`, when the file moved under you.
 *
 * HAND-WRITTEN, and it has to be: `routers/config.py::save_config` raises this as an
 * `HTTPException`, so it is not the route's `response_model` and
 * `openapi-typescript` never sees it. This is the one shape in this file that
 * `make lint-generated` cannot hold to the tree -- if that detail dict changes
 * server-side, nothing here will notice. Keep the two in the same commit.
 *
 * `current_version` is what makes the recovery path recover: adopting it lets
 * the next save carry a `base_version` the server will accept. Without it every
 * subsequent save 409s again until the page is reloaded.
 */
export interface ConfigConflict {
  detail?: {
    message?: string
    current_version?: string
    current_content?: string
  }
}
